(6102, 0, 1, 3801, 1073741888, 0, 11, 0, 0, 0, 10, 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 'Ironforge Airfields', 16712190, 0, 0, 0, 0, 0, -500.0, 0.0, 0),
