INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(60629, 0, 0, 'Long, long ago, we first discovered the Azurestone when digging the very halls of Ironforge itself, at the beginning, it was simply seen as a beautiful blue jewel and held a natural value. Quite quickly thereafter, the power of the Azurestone was discovered by a dwarf naturally gifted with the arcana.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66695'),
(60629, 1, 0, 'Huidgrar Azurebrow was the one who studied the stone, and taught others of its power, the name \'Azurestone\' came from his name, and those that studied beneath him created \'The Azurestone Order\'. The Order has been pivotal in many key points in history, from the War of the Three Hammers, to when the orcs were getting close to Ironforge itself!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66696'),
(60629, 2, 0, 'When Huidgrar died from his rather long and vibrant life, the Azurestone Order fell with him, falling into obscurity with time. It is up to us, the naturally gifted of our kind to reignite this ancient group, and to show the world our prowess with fire, frost, and the arcane!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66697'),
(61436, 0, 0, 'Blasted... It would appear that the materials I am working with are not enough... Wait a second, I got it!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66605'),
(1255, 100, 0, 'Oh, he sent you for ore did he? Make sure he gets it this time.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66810');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9060629, 'We dwarven mages are that of The Azurestone Order, long ago when the very caves of Ironforge were being mined, we came across an old, and rather magically potent stone. This stone was studied by the mages of Dalaran, and has been kept within our hands since that very day.\n\nIt is with this stone that many of the first dwarven mages had gotten their footing within the realm of arcana. If you see any of our kin that are naturally gifted with magic, guide them here.', 'We dwarven mages are that of The Azurestone Order, long ago when the very caves of Ironforge were being mined, we came across an old, and rather magically potent stone. This stone was studied by the mages of Dalaran, and has been kept within our hands since that very day.\n\nIt is with this stone that many of the first dwarven mages had gotten their footing within the realm of arcana. If you see any of our kin that are naturally gifted with magic, guide them here.', 1, 0);
